CREATE TYPE public.app_role AS ENUM ('editor');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.editor_invitations (email text PRIMARY KEY);
GRANT ALL ON public.editor_invitations TO service_role;
ALTER TABLE public.editor_invitations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.profiles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', biography text NOT NULL DEFAULT '');
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY own_profile_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE FUNCTION public.initialize_editor_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN
INSERT INTO public.profiles(user_id) VALUES (NEW.id) ON CONFLICT DO NOTHING;
IF NEW.email_confirmed_at IS NOT NULL AND EXISTS (SELECT 1 FROM public.editor_invitations WHERE lower(email) = lower(NEW.email)) THEN
INSERT INTO public.user_roles(user_id, role) VALUES (NEW.id, 'editor') ON CONFLICT DO NOTHING;
END IF;
RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.initialize_editor_identity() FROM PUBLIC;
CREATE TRIGGER initialize_editor_identity AFTER INSERT OR UPDATE OF email_confirmed_at, email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.initialize_editor_identity();
CREATE TABLE public.ai_research_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, field text NOT NULL, scope text NOT NULL DEFAULT '', report text NOT NULL DEFAULT '', sources jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'running' CHECK (status IN ('running','complete','stopped','failed')), error_message text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.ai_research_reports TO authenticated;
GRANT ALL ON public.ai_research_reports TO service_role;
ALTER TABLE public.ai_research_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY editor_report_read ON public.ai_research_reports FOR SELECT TO authenticated USING (user_id = auth.uid() AND public.has_role(auth.uid(), 'editor'));
CREATE POLICY editor_report_insert ON public.ai_research_reports FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND public.has_role(auth.uid(), 'editor'));
CREATE POLICY editor_report_update ON public.ai_research_reports FOR UPDATE TO authenticated USING (user_id = auth.uid() AND public.has_role(auth.uid(), 'editor')) WITH CHECK (user_id = auth.uid() AND public.has_role(auth.uid(), 'editor'));
CREATE INDEX editor_report_history ON public.ai_research_reports(user_id, created_at DESC);
CREATE TABLE public.ai_gateway_access (id text PRIMARY KEY DEFAULT 'editor-research', blocked boolean NOT NULL DEFAULT false, status_code integer, message text);
GRANT SELECT ON public.ai_gateway_access TO authenticated;
GRANT ALL ON public.ai_gateway_access TO service_role;
ALTER TABLE public.ai_gateway_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY editors_read_ai_access ON public.ai_gateway_access FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'editor'));
